document.addEventListener("click",e=>{const chip=e.target.closest(".chip");if(!chip)return;const close=e.target.closest(".chip-close");if(close){e.stopPropagation();chip.style.opacity="0";setTimeout(()=>chip.remove(),150)}else if(chip.hasAttribute("aria-pressed")&&!chip.querySelector(".chip-close")){const pressed=chip.getAttribute("aria-pressed")==="true";chip.setAttribute("aria-pressed",String(!pressed))}});